using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Globalization;using System.Text;using System.Xml;
namespace BeamScheduleFormatter {
class WindNode {public double X,Y,V;}
class WindLookup {public double V,X,Y,Distance;public int Map,Triangle;public double[] Weights;public WindNode[] Nodes;public bool Coastal;}
class WindSurface {public string Category;public int Map;public WindNode[] Nodes;public int[][] Faces;}
static partial class WindTin {
 static readonly object gate=new object();static readonly List<WindSurface> surfaces=new List<WindSurface>();static double[] transform;
 static void Load(){lock(gate){if(surfaces.Count>0)return;using(var stream=typeof(WindTin).Assembly.GetManifestResourceStream("WindSurfaces.txt")){if(stream==null)throw new Exception("Embedded wind contours missing.");using(var reader=new StreamReader(stream)){if(reader.ReadLine()!="DTCE-WIND-TIN-1")throw new Exception("Wind contour format changed.");transform=Numbers(reader.ReadLine());while(!reader.EndOfStream){var row=reader.ReadLine().Split(',');var s=new WindSurface{Category=row[1],Map=int.Parse(row[2]),Nodes=new WindNode[int.Parse(row[3])],Faces=new int[int.Parse(row[4])][]};for(int n=0;n<s.Nodes.Length;n++){var p=Numbers(reader.ReadLine());s.Nodes[n]=new WindNode{X=p[0],Y=p[1],V=p[2]};}for(int n=0;n<s.Faces.Length;n++)s.Faces[n]=reader.ReadLine().Split(',').Select(int.Parse).ToArray();surfaces.Add(s);}}}}}
 static double[] Numbers(string value){return value.Split(',').Select(x=>double.Parse(x,CultureInfo.InvariantCulture)).ToArray();}
 public static void Validate(double lat,double lon){if(!Finite(lat)||!Finite(lon)||lat<4.3||lat>21.4||lon<116.5||lon>127)throw new Exception("Enter Philippine latitude 4.3–21.4 N and longitude 116.5–127 E in decimal degrees.");}
 public static bool Finite(double x){return !double.IsNaN(x)&&!double.IsInfinity(x);}
 public static double[] Barycentric(WindNode a,WindNode b,WindNode c,double x,double y){double d=(b.Y-c.Y)*(a.X-c.X)+(c.X-b.X)*(a.Y-c.Y);if(Math.Abs(d)<1e-10)return null;double u=((b.Y-c.Y)*(x-c.X)+(c.X-b.X)*(y-c.Y))/d,v=((c.Y-a.Y)*(x-c.X)+(a.X-c.X)*(y-c.Y))/d;return new[]{u,v,1-u-v};}
 public static WindLookup At(double lat,double lon,string category){Validate(lat,lon);Load();double x=transform[0]*(lon-121)+transform[1],y=transform[2]*(180/Math.PI*Math.Log(Math.Tan(Math.PI/4+lat*Math.PI/360))-13)+transform[3];var s=surfaces.Single(z=>z.Category==category);for(int n=0;n<s.Faces.Length;n++){var nodes=s.Faces[n].Select(i=>s.Nodes[i]).ToArray();var weights=Barycentric(nodes[0],nodes[1],nodes[2],x,y);if(weights!=null&&weights.All(w=>w>=-1e-9))return new WindLookup{V=weights.Select((w,i)=>w*nodes[i].V).Sum(),X=x,Y=y,Map=s.Map,Triangle=n,Weights=weights,Nodes=nodes};}var nearest=s.Nodes.OrderBy(p=>(p.X-x)*(p.X-x)+(p.Y-y)*(p.Y-y)).First();return new WindLookup{V=nearest.V,X=x,Y=y,Map=s.Map,Triangle=-1,Weights=new[]{1.0},Nodes=new[]{nearest},Coastal=true,Distance=Math.Sqrt((nearest.X-x)*(nearest.X-x)+(nearest.Y-y)*(nearest.Y-y))};}
}
class WindSample {public double Lat,Lon,D,Z;public int Cover;}
class WindCoverGrid {public int Size;public double North,South,West,East;public byte[] Codes;}
class WindTerrain {/* the engineer confirmed a flat site: no hill, ridge or escarpment, Kzt = 1 (owner: "flat lang naman itsura") */public bool UserFlat;public WindCoverGrid CoverGrid;public double Lat,Lon,Radius;public DateTime Acquired;public readonly List<WindSample>[] Rays=Enumerable.Range(0,24).Select(i=>new List<WindSample>()).ToArray();public readonly List<WindSample>[] Cross=Enumerable.Range(0,8).Select(i=>new List<WindSample>()).ToArray();}
class WindDirection {public string Name,Exposure,Shape,Status;public double H=double.NaN,Lh=double.NaN,X=double.NaN,K1=double.NaN,K2=double.NaN,K3=double.NaN,Kzt=double.NaN,Kz=double.NaN,Qz=double.NaN;public List<WindSample> Profile;public WindExposureAudit ExposureAudit;public readonly List<string[]> TopographicChecks=new List<string[]>();public string TopographicReason="";}
static partial class WindAssessment {
 public static readonly string[] Directions={"N","NE","E","SE","S","SW","W","NW"};
 public static double[] Destination(double lat,double lon,double bearing,double metres){double d=metres/6371008.8,p=lat*Math.PI/180,l=lon*Math.PI/180,a=bearing*Math.PI/180,p2=Math.Asin(Math.Sin(p)*Math.Cos(d)+Math.Cos(p)*Math.Sin(d)*Math.Cos(a));return new[]{p2*180/Math.PI,(l+Math.Atan2(Math.Sin(a)*Math.Sin(d)*Math.Cos(p),Math.Cos(d)-Math.Sin(p)*Math.Sin(p2)))*180/Math.PI};}
 public static string Roughness(int code){return code==10||code==50||code==95?"B":code==80?"D":new[]{20,30,40,60,90,100}.Contains(code)?"C":"?";}
 public static double DFetch(double height){return Math.Max(1524,20*height);}
 public static double DTransition(double height){return Math.Max(182.88,20*height);}
 public static double RequiredRadius(double height){return Math.Max(3200,Math.Max(BFetch(height),DFetch(height)+DTransition(height)));}
 public static double BFetch(double height){return height<=9.1?457.2:Math.Max(792.48,20*height);}
 public static string Exposure(IEnumerable<List<WindSample>> sector,double height){return AssessExposure(sector,height).Exposure;}
 public static string Exposure(WindTerrain terrain,int direction,double height){return AssessExposure(terrain,direction,height).Exposure;}
 public static double[] Factors(double h,double lh,double x,double z,string exposure,string shape){if(!WindTin.Finite(h)||!WindTin.Finite(lh)||!WindTin.Finite(x)||!WindTin.Finite(z)||h<0||lh<=0||z<0||!new[]{"B","C","D"}.Contains(exposure)||!new[]{"Hill","Ridge","Escarpment"}.Contains(shape))throw new Exception("Check topographic geometry/exposure.");int i=exposure=="B"?0:exposure=="C"?1:2;double a=shape=="Ridge"?new[]{1.3,1.45,1.55}[i]:shape=="Escarpment"?new[]{.75,.85,.95}[i]:new[]{.95,1.05,1.15}[i],effective=Math.Max(lh,2*h),k1=a*Math.Min(.5,h/lh),mu=shape=="Escarpment"&&x<0?4:1.5,gamma=shape=="Ridge"?3:shape=="Escarpment"?2.5:4,k2=Math.Max(0,1-Math.Abs(x)/(mu*effective)),k3=Math.Exp(-gamma*z/effective);return new[]{k1,k2,k3,Math.Pow(1+k1*k2*k3,2)};}
 public static double Kz(double height,string exposure){double alpha=exposure=="B"?7:exposure=="C"?9.5:11.5,zg=exposure=="B"?365.76:exposure=="C"?274.32:213.36;return 2.01*Math.Pow(Math.Max(4.572,height)/zg,2/alpha);}
}
static class WindTerrainXml {
 static string F(double n){return n.ToString("R",CultureInfo.InvariantCulture);}static double N(XmlElement e,string name){double n;if(!double.TryParse(e.GetAttribute(name),NumberStyles.Float,CultureInfo.InvariantCulture,out n)||!WindTin.Finite(n))throw new Exception("Invalid terrain sample.");return n;}
 public static void Write(XmlElement root,WindTerrain data){if(data==null)return;var node=root.OwnerDocument.CreateElement("WindTerrain");root.AppendChild(node);node.SetAttribute("version","1");node.SetAttribute("lat",F(data.Lat));node.SetAttribute("lon",F(data.Lon));node.SetAttribute("radius",F(data.Radius));node.SetAttribute("utc",data.Acquired.ToUniversalTime().ToString("o"));if(data.CoverGrid!=null){var grid=root.OwnerDocument.CreateElement("CoverGrid");node.AppendChild(grid);grid.SetAttribute("size",data.CoverGrid.Size.ToString());grid.SetAttribute("north",F(data.CoverGrid.North));grid.SetAttribute("south",F(data.CoverGrid.South));grid.SetAttribute("west",F(data.CoverGrid.West));grid.SetAttribute("east",F(data.CoverGrid.East));grid.InnerText=Convert.ToBase64String(data.CoverGrid.Codes);}for(int type=0;type<2;type++){var groups=type==0?data.Rays:data.Cross;for(int i=0;i<groups.Length;i++){var ray=root.OwnerDocument.CreateElement(type==0?"Ray":"Cross");ray.SetAttribute("index",i.ToString(CultureInfo.InvariantCulture));node.AppendChild(ray);foreach(var p in groups[i]){var sample=root.OwnerDocument.CreateElement("Sample");ray.AppendChild(sample);sample.SetAttribute("lat",F(p.Lat));sample.SetAttribute("lon",F(p.Lon));sample.SetAttribute("d",F(p.D));if(WindTin.Finite(p.Z))sample.SetAttribute("z",F(p.Z));sample.SetAttribute("cover",p.Cover.ToString(CultureInfo.InvariantCulture));}}}}
 public static WindTerrain Read(XmlElement root){var node=root["WindTerrain"];if(node==null)return null;if(node.GetAttribute("version")!="1")throw new Exception("Unsupported terrain snapshot.");var data=new WindTerrain{Lat=N(node,"lat"),Lon=N(node,"lon"),Radius=N(node,"radius"),Acquired=DateTime.Parse(node.GetAttribute("utc"),CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind)};var savedGrid=node["CoverGrid"];if(savedGrid!=null){int size=int.Parse(savedGrid.GetAttribute("size"));if(size<16||size>128)throw new Exception("Invalid roughness grid size.");var grid=new WindCoverGrid{Size=size,North=N(savedGrid,"north"),South=N(savedGrid,"south"),West=N(savedGrid,"west"),East=N(savedGrid,"east"),Codes=Convert.FromBase64String(savedGrid.InnerText)};if(grid.Codes.Length!=size*size||grid.Codes.Any(c=>c>100)||grid.North<=grid.South||grid.East<=grid.West||grid.North>90||grid.South< -90||grid.West< -180||grid.East>180)throw new Exception("Invalid roughness grid.");data.CoverGrid=grid;}WindTin.Validate(data.Lat,data.Lon);if(data.Radius<2200||data.Radius>10000)throw new Exception("Invalid terrain extent.");for(int type=0;type<2;type++){var groups=type==0?data.Rays:data.Cross;var rays=node.SelectNodes(type==0?"Ray":"Cross");if(rays.Count!=groups.Length)throw new Exception("Incomplete terrain snapshot.");foreach(XmlElement ray in rays){int index=int.Parse(ray.GetAttribute("index"));if(index<0||index>=groups.Length||groups[index].Count>0||ray.ChildNodes.Count>250)throw new Exception("Invalid terrain ray.");foreach(XmlElement p in ray.SelectNodes("Sample")){var sample=new WindSample{Lat=N(p,"lat"),Lon=N(p,"lon"),D=N(p,"d"),Z=p.HasAttribute("z")?N(p,"z"):double.NaN,Cover=int.Parse(p.GetAttribute("cover"))};if(Math.Abs(sample.Lat)>90||Math.Abs(sample.Lon)>180||Math.Abs(sample.D)>data.Radius+.01||sample.Cover<0||sample.Cover>100)throw new Exception("Invalid terrain value.");groups[index].Add(sample);}if(groups[index].Count<10||groups[index].Zip(groups[index].Skip(1),(a,b)=>a.D>=b.D).Any(b=>b))throw new Exception("Invalid terrain order.");}}return data;}
}
}
